"use server";

import { revalidateTag } from "next/cache";

// Define the Post type
interface Post {
  id: string;
  title: string;
  content: string;
}

// Mock database for posts
let posts: Post[] = [];

// Server Action to create a new post
export async function createPost(title: string, content: string): Promise<Post> {
  const newPost: Post = {
    id: Date.now().toString(),
    title,
    content,
  };

  posts.push(newPost);

  // Invalidate the "posts" cache tag to ensure fresh data is fetched
  revalidateTag("posts");

  return newPost;
}

// Function to get all posts
export async function getPosts(): Promise<Post[]> {
  return posts;
}

